import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"Installation Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/installation.md","filePath":"en/guide/installation.md"}`),a={name:`en/guide/installation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="installation-guide" tabindex="-1">Installation Guide <a class="header-anchor" href="#installation-guide" aria-label="Permalink to “Installation Guide”">​</a></h1><p>This guide applies to Zotero PDF2zh <strong>v4.1.1</strong> (including v4.1.0 features). Starting with v4.1.0, the Server source, Zotero plugin, and Python translation environment are maintained separately. Normal users do not need to choose exact <code>pdf2zh_next</code>, BabelDOC, or PyMuPDF versions manually.</p><div class="tip custom-block"><p class="custom-block-title">Before You Begin</p><p>Recommended:</p><ul><li><strong>Python 3.12</strong></li><li><strong>Zotero 7 / 8 / 9 / 10</strong></li><li><strong>uv</strong> for new installations, or an existing conda setup</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Windows Conda users</p><p>Use <strong>v4.1.1</strong> or later. v4.1.0 looked for Conda Python at <code>&lt;env&gt;\\\\Scripts\\\\python.exe</code> and could treat a healthy environment as broken. The correct path is <code>&lt;env&gt;\\\\python.exe</code> at the environment root.</p></div><h2 id="_1-download-the-server" tabindex="-1">1. Download the Server <a class="header-anchor" href="#_1-download-the-server" aria-label="Permalink to “1. Download the Server”">​</a></h2><p>Download <code>server.zip</code> from the latest GitHub Release. Do not use a static zip from the repository <code>main</code> branch:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://github.com/guaguastandup/zotero-pdf2zh/releases/latest/download/server.zip</span></span></code></pre></div><p>After extracting, the layout should look like:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zotero-pdf2zh/</span></span>
<span class="line"><span>└── server/</span></span>
<span class="line"><span>    ├── server.py</span></span>
<span class="line"><span>    ├── requirements.txt</span></span>
<span class="line"><span>    ├── update_packages.py</span></span>
<span class="line"><span>    ├── config/</span></span>
<span class="line"><span>    └── utils/</span></span></code></pre></div><p>Enter the Server directory:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span></span></code></pre></div><h2 id="_2-install-server-runtime-dependencies" tabindex="-1">2. Install Server Runtime Dependencies <a class="header-anchor" href="#_2-install-server-runtime-dependencies" aria-label="Permalink to “2. Install Server Runtime Dependencies”">​</a></h2><p>This installs only the dependencies required to run the Server itself, such as Flask, TOML and PDF utilities. You do <strong>not</strong> need to install <code>pdf2zh_next</code> or BabelDOC manually:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.txt</span></span></code></pre></div><h2 id="_3-recommended-install-uv" tabindex="-1">3. Recommended: Install uv <a class="header-anchor" href="#_3-recommended-install-uv" aria-label="Permalink to “3. Recommended: Install uv”">​</a></h2><p>If this machine does not already have a managed translation environment, install uv:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># macOS / Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -LsSf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://astral.sh/uv/install.sh</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Windows PowerShell</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">powershell</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ExecutionPolicy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ByPass</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;irm https://astral.sh/uv/install.ps1 | iex&quot;</span></span></code></pre></div><p>Verify:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Existing conda users do not need to migrate to uv. The default <code>env_tool=auto</code> keeps an existing uv or conda project environment; only a fresh installation prefers uv.</p><h2 id="_4-start-the-server" tabindex="-1">4. Start the Server <a class="header-anchor" href="#_4-start-the-server" aria-label="Permalink to “4. Start the Server”">​</a></h2><p>For normal use:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span></span></code></pre></div><p>Default address:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://127.0.0.1:8890</span></span></code></pre></div><p>The Server binds to <code>127.0.0.1</code> by default. Only expose it to other devices when you intentionally need remote access:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Remote access</p><p><code>--host 0.0.0.0</code> exposes the Server to other devices reachable on the current network. Use it only when you understand the firewall/network implications.</p></div><h2 id="_5-what-happens-on-the-first-translation" tabindex="-1">5. What Happens on the First Translation? <a class="header-anchor" href="#_5-what-happens-on-the-first-translation" aria-label="Permalink to “5. What Happens on the First Translation?”">​</a></h2><p>New users do not need to run <code>pip install pdf2zh_next</code> first.</p><p>On the first real <code>pdf2zh_next</code> translation, the Server automatically:</p><ol><li>chooses the environment manager (uv for a fresh setup);</li><li>probes PyPI, USTC, TUNA, Aliyun and optional custom indexes;</li><li>finds or creates the canonical environment;</li><li>installs a compatible <code>pdf2zh_next</code> (<code>&gt;=2.9.0,&lt;3.0.0</code>) and its dependencies in that environment;</li><li>validates dependencies and DeepSeek V4 capability.</li></ol><p>If installation fails, retry later with <code>python update_packages.py</code>.</p><h2 id="_6-existing-users-upgrading-to-v4-1-0-v4-1-1" tabindex="-1">6. Existing Users Upgrading to v4.1.0 / v4.1.1 <a class="header-anchor" href="#_6-existing-users-upgrading-to-v4-1-0-v4-1-1" aria-label="Permalink to “6. Existing Users Upgrading to v4.1.0 / v4.1.1”">​</a></h2><p>If an existing uv or conda translation environment is found, the new Server asks once whether to perform a safe refresh:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Existing Python translation environment detected</span></span>
<span class="line"><span>Current pdf2zh_next: ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Y] Check and update (recommended)</span></span>
<span class="line"><span>[N] Keep current environment</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Choose [Y/n]:</span></span></code></pre></div><p>Press Enter to select <code>Y</code>.</p><p>The update path is:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>install in the current conda/uv environment</span></span>
<span class="line"><span>→ validation</span></span></code></pre></div><p>Staging / backup environments are no longer created. If you choose <code>N</code>, existing capabilities continue to work. DeepSeek V4 defaults to no thinking, so an older runtime can still translate. If you later enable thinking, the Server checks whether the runtime supports it before an API request.</p><p>To retry later:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update_packages.py</span></span></code></pre></div><p>This command automatically detects an existing uv or conda environment; if no managed environment exists, it prefers uv.</p><h2 id="_7-conda-users" tabindex="-1">7. conda Users <a class="header-anchor" href="#_7-conda-users" aria-label="Permalink to “7. conda Users”">​</a></h2><p>If your previous installation already uses conda, simply run:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span></span></code></pre></div><p>The default <code>auto</code> mode discovers and keeps the existing conda environment.</p><p>To force conda only:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env_tool=conda</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update_packages.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> conda</span></span></code></pre></div><p>An explicitly selected manager is strict: conda failure does not silently switch to uv, and vice versa.</p><p>On Windows, Conda Python is <code>&lt;conda&gt;\\\\envs\\\\zotero-pdf2zh-next-venv\\\\python.exe</code>. uv / venv use <code>Scripts\\\\python.exe</code>. v4.1.1 distinguishes these paths.</p><h2 id="_8-without-a-managed-virtual-environment-advanced" tabindex="-1">8. Without a Managed Virtual Environment (Advanced) <a class="header-anchor" href="#_8-without-a-managed-virtual-environment-advanced" aria-label="Permalink to “8. Without a Managed Virtual Environment (Advanced)”">​</a></h2><p>Only use this when you intentionally maintain the Python environment yourself:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --enable_venv=False</span></span></code></pre></div><p>The Server will not update your system Python environment in this mode. Runtime capability checks such as DeepSeek V4 protection still apply.</p><h2 id="_9-install-the-zotero-plugin" tabindex="-1">9. Install the Zotero Plugin <a class="header-anchor" href="#_9-install-the-zotero-plugin" aria-label="Permalink to “9. Install the Zotero Plugin”">​</a></h2><p>Latest XPI:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://github.com/guaguastandup/zotero-pdf2zh/releases/latest/download/zotero-pdf-2-zh.xpi</span></span></code></pre></div><p>Steps:</p><ol><li>Zotero → <strong>Tools → Add-ons</strong>;</li><li>drag the downloaded <code>.xpi</code> into the Add-ons window;</li><li>restart Zotero after installation;</li><li>open <strong>Tools → PDF2zh Preferences</strong>;</li><li>keep the Python Server URL at <code>http://127.0.0.1:8890</code> unless you intentionally changed it.</li></ol><h2 id="_10-default-server-arguments" tabindex="-1">10. Default Server Arguments <a class="header-anchor" href="#_10-default-server-arguments" aria-label="Permalink to “10. Default Server Arguments”">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--host</code></td><td><code>127.0.0.1</code></td><td>Localhost-only by default</td></tr><tr><td><code>--port</code></td><td><code>8890</code></td><td>Server port</td></tr><tr><td><code>--enable_venv</code></td><td><code>True</code></td><td>Enable managed translation environments</td></tr><tr><td><code>--env_tool</code></td><td><code>auto</code></td><td>Keep existing uv/conda; prefer uv for a fresh environment</td></tr><tr><td><code>--check_update</code></td><td><code>True</code></td><td>Check Server updates on startup</td></tr><tr><td><code>--update_source</code></td><td><code>gitee</code></td><td>Preferred update source; both GitHub and Gitee are tried</td></tr><tr><td><code>--enable_mirror</code></td><td><code>True</code></td><td>Enable package-download source optimization</td></tr><tr><td><code>--skip_install</code></td><td><code>False</code></td><td>Disable automatic environment creation/repair</td></tr></tbody></table><p>Examples:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Change port</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9999</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Force uv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env_tool=uv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Force conda</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env_tool=conda</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Prefer GitHub for Server updates (Gitee is still tried if GitHub fails)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update_source=github</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Allow LAN access (advanced)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><h2 id="_11-windows-standalone-exe-advanced" tabindex="-1">11. Windows Standalone exe (Advanced) <a class="header-anchor" href="#_11-windows-standalone-exe-advanced" aria-label="Permalink to “11. Windows Standalone exe (Advanced)”">​</a></h2><p>A Windows standalone <code>pdf2zh_next</code> executable can also be used:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --enable_winexe=True</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --winexe_path=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;path-to-pdf2zh.exe&gt;&quot;</span></span></code></pre></div><p>The standalone executable must be maintained separately. DeepSeek V4 thinking is only required when the user enables it; an old exe can still translate with thinking disabled.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>Keep <code>server.py</code> running while translating.</li><li>Do not use <code>--no-deps</code> to force incompatible BabelDOC / PyMuPDF / pdf2zh_next combinations.</li><li>Prefer the startup update prompt or <code>python update_packages.py</code> for translation-environment maintenance.</li><li>Some malformed PDFs may still trigger upstream BabelDOC / PyMuPDF parser failures; Zotero PDF2zh does not automatically rewrite or rasterize every user PDF.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><a href="/en/guide/configuration.html">Configuration</a></li><li><a href="/en/guide/translation-options.html">Translation Options</a></li><li><a href="/en/guide/extra-params.html">Extra Parameters</a></li><li><a href="/en/guide/package-update.html">Translation Environment Updates</a></li><li><a href="/en/guide/faq/">FAQ</a></li></ul>`,72)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};